package com.bank.spark.service;

import com.bank.spark.model.Txn;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;
import java.util.stream.Collectors;

// Simulates window functions: running sum, row_number by amount, lag amount.
public class WindowEngine {

    private static final Logger log = Logger.getLogger(WindowEngine.class.getName());

    // Returns annotated lines: each original row + runningTotal, rankByAmount, prevAmount.
    public List<String> annotate(List<Txn> txns) {
        List<String> out = new ArrayList<>();

        // PARTITION BY accountId
        Map<String, List<Txn>> byAccount = txns.stream()
                .collect(Collectors.groupingBy(Txn::getAccountId));

        for (var entry : byAccount.entrySet()) {
            List<Txn> partition = new ArrayList<>(entry.getValue());
            // ORDER BY ts for running sum and lag
            partition.sort(Comparator.comparingLong(Txn::getTs));

            // ROW_NUMBER() OVER (PARTITION BY accountId ORDER BY amount DESC)
            List<Txn> byAmountDesc = new ArrayList<>(partition);
            byAmountDesc.sort(Comparator.comparing(Txn::getAmount).reversed());

            BigDecimal running = BigDecimal.ZERO;
            BigDecimal prev = null;
            for (Txn t : partition) {
                running = running.add(t.getAmount());                       // SUM() OVER running
                int rank = byAmountDesc.indexOf(t) + 1;                      // ROW_NUMBER by amount
                String prevStr = (prev == null) ? "none" : prev.toPlainString(); // LAG(amount)
                out.add(entry.getKey() + " ts=" + t.getTs()
                        + " amt=" + t.getAmount()
                        + " running=" + running
                        + " rankByAmt=" + rank
                        + " prevAmt=" + prevStr);
                prev = t.getAmount();
            }
        }
        log.info(() -> "Annotated " + out.size() + " rows (NONE collapsed)");
        return out;
    }
}
