package com.bank.spark;

import com.bank.spark.model.Txn;
import com.bank.spark.service.WindowEngine;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: window functions annotate each row without collapsing.
public class WindowFunctionsDemo {

    private static final Logger log = Logger.getLogger(WindowFunctionsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        WindowEngine engine = new WindowEngine();

        List<Txn> txns = List.of(
            new Txn("SAV2001", 1, new BigDecimal("50000")),
            new Txn("SAV2001", 2, new BigDecimal("3000")),
            new Txn("SAV2001", 3, new BigDecimal("12000")),
            new Txn("CUR3001", 1, new BigDecimal("9000")),
            new Txn("CUR3001", 2, new BigDecimal("25000")));

        for (String line : engine.annotate(txns)) {
            log.info(line);
        }
        log.info("Window functions demo complete.");
    }
}
